ControlPropertyState.AutoRuleBindingString:
RoundUp(
    ((drp_AddOP_BC.Selected.Meta * 36) * txt_CantMaquinas_BC.Text) * Sum(
        Filter(
            jobmatl,
            item = ThisItem.Value && job = drp_AddOrden_BC.Selected.Value && oper_num = Value(drp_AddOP_BC.Selected.Operacion)
        ),
        matl_qty
    ),
    0
)

If(
    IsBlank(drp_AddOrden_BC_1.Selected.Value) || IsBlank(drp_AddOP_BC_1.Selected.Operacion),
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "Debe seleccionar una Orden y una Operacion"
            }
        }
    ),
    IsBlank(txt_CantMaquinas_BC_4.Text) || txt_CantMaquinas_BC_4.Text = "0",
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "La Orden debe tener almenos una maquina asignada"
            }
        }
    ),
    CountRows(glr_EditMateriales_BC.AllItems) <= 0,
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "La lista de materiales no puede estar vacia"
            }
        }
    ),
    UpdateContext({Guardando: true});
    ForAll(
        glr_EditMateriales_BC.AllItems,
        Collect(
            Controlador_Bodegas,
            {
                Orden: drp_AddOrden_BC_1.Selected.Value,
                Operacion: drp_AddOP_BC_1.Selected.Operacion,
                Material: ThisRecord.Value,
                Descripcion: ThisRecord.EditOP_BC.Text,
                Matl_Qty: Value(ThisRecord.EditMaximo_BC.Text),
                Maximo: Value(ThisRecord.EditUsado_BC.Text)
            }
        )
    );
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 2,
                Texto: "La Orden se agrego con exito"
            }
        }
    );
    UpdateContext({Guardando: false});
    Reset(drp_AddOP_BC_1);
    Reset(drp_AddOrden_BC_1);
    Reset(glr_EditMateriales_BC);
    UpdateContext(
        {
            VerMaquinas: false,
            agregarOrden: !agregarOrden
        }
    )
)

RoundUp(
    ((drp_AddOP_BC_1.Selected.Meta * 36) * txt_CantMaquinas_BC_4.Text) * Sum(
        Filter(
            jobmatl,
            item = ThisItem.Value && job = drp_AddOrden_BC_1.Selected.Value && oper_num = Value(drp_AddOP_BC_1.Selected.Operacion)
        ),
        matl_qty
    ),
    0
)

Reset(drp_AddOP_BC_1);
Reset(drp_AddOrden_BC_1);
Reset(glr_AddMateriales_BC_2);
UpdateContext({VerMaquinas: false, agregarOrden: !agregarOrden})

RoundUp(
    ((drp_AddOP_BC.Selected.Meta * 36) * txt_CantMaquinas_BC.Text) * Sum(
        Filter(
            jobmatl,
            item = ThisItem.Value && job = drp_AddOrden_BC.Selected.Value && oper_num = Value(drp_AddOP_BC.Selected.Operacion)
        ),
        matl_qty
    ),
    0
)
